import { useCallback, useRef } from 'preact/hooks';

interface Props {
  loadMore: () => unknown,
  space: number,
}

const useInfinityScroll = ({ loadMore, space }: Props): (evt) => unknown => {
  const callbackRef = useRef(loadMore);
  callbackRef.current = loadMore;

  const ref = useRef(null);

  return useCallback((evt) => {
    const { scrollHeight, scrollTop, offsetHeight } = evt.currentTarget;

    if (ref.current === scrollHeight) return;
    if ((scrollTop + offsetHeight) > scrollHeight - space) {
      ref.current = scrollHeight;
      callbackRef.current();
    }
  }, []);
};

export default useInfinityScroll;
